'use strict';
const planOptions=(chosen)=>Object.values(RijaaPlans.plans).map(p=>`<option value="${p.id}" ${p.id===chosen?'selected':''}>${p.name} · ${p.sale} ريال · ${p.cards} بطاقة</option>`).join('');
let requestedPlan='basic',billingPeriod='month';
whatsapp=function(){const a=account(),p=RijaaPlans.plans[requestedPlan]||RijaaPlans.forAccount(a);const message=`مرحبًا، أرغب في باقة رجعة ${p.name} بسعر ${billingPeriod==='year'?p.annual:p.sale} ريال ${billingPeriod==='year'?'سنويًا لمدة 12 شهرًا بسعر مخفّض':'شهريًا'}، ${p.cards} تصميم بطاقة ولاء و${p.employees} موظف، وعملاء غير محدودين.${a?`\nمعرّف الحساب: ${a.id}\nالنشاط: ${db.shops.find(s=>s.id===a.shop)?.name}`:''}`;location.assign(`https://wa.me/${db.settings.whatsapp}?text=${encodeURIComponent(message)}`);};
const planHome=homeHTML;
homeHTML=function(){const box=document.createElement('div');box.innerHTML=planHome();box.querySelector('.pricing').innerHTML=`<div class="pricing-copy"><div class="eyebrow">ثلاث باقات تناسب نشاطك</div><h2>ابدأ ببطاقة، وكبّر برنامجك.</h2><p>العدد يخص تصاميم برامج الولاء. بطاقات العملاء غير محدودة في جميع الباقات.</p><div class="billing-switch" aria-label="مدة الاشتراك"><button class="btn glow-button ${billingPeriod==='month'?'active':''}" data-action="billing-period" data-period="month" aria-pressed="${billingPeriod==='month'}"><span class="glow-orbit" aria-hidden="true"><span>↗</span></span><span>شهري</span></button><button class="btn glow-button ${billingPeriod==='year'?'active':''}" data-action="billing-period" data-period="year" aria-pressed="${billingPeriod==='year'}"><span class="glow-orbit" aria-hidden="true"><span>↗</span></span><span>سنوي</span><small>شهران مجانيان</small></button></div></div><div class="plans-grid">${Object.values(RijaaPlans.plans).map(p=>`<article class="price-card premium-plan ${p.id==='growth'?'recommended-plan':''}"><div class="plan-top"><span class="plan-name">${p.name}</span><span class="discount-badge">${billingPeriod==='year'?'شهران مجانيان':`خصم ${p.discount}%`}</span></div><p class="plan-description">${p.id==='basic'?'أول خطوة لعودة عملائك':p.id==='growth'?'مساحة أكبر لولاء أقوى':'برنامج يواكب طموح نشاطك'}</p><div class="plan-price-line"><del>${billingPeriod==='year'?p.sale*12:p.price} ريال</del><span>وفّر ${billingPeriod==='year'?(p.sale*12-p.annual).toLocaleString('en-US'):(p.price-p.sale).toFixed(2)} ريال ${billingPeriod==='year'?'سنويًا':'شهريًا'}</span></div><div class="price">${(billingPeriod==='year'?p.annual:p.sale).toLocaleString('en-US')}<span> ريال / ${billingPeriod==='year'?'سنة':'شهر'}</span></div><div class="feature-list"><div>${icon('check')} ${p.cards} ${p.cards===1?'تصميم بطاقة ولاء':'تصاميم بطاقات ولاء'}</div><div>${icon('check')} ${p.employees} ${p.employees===1?'حساب موظف':'حسابات موظفين'}</div><div>${icon('check')} عملاء غير محدودين</div><div>${icon('check')} برامج زيارات وخصومات ونقاط</div><div>${icon('check')} تخصيص الألوان والشعار والخلفية</div><div>${icon('check')} إدارة العملاء وسجل العمليات</div></div><button class="btn lime full" data-action="choose-plan" data-plan="${p.id}">اشترك عبر واتساب</button><small>${billingPeriod==='year'?'اشتراك 12 شهرًا بسعر مخفّض مقارنة بالدفع الشهري.':'الدفع والتفعيل عبر الإدارة.'}</small></article>`).join('')}</div>`;return box.innerHTML;};
const oldAccountRows=accountRows;
accountRows=function(accounts){const box=document.createElement('tbody');box.innerHTML=oldAccountRows(accounts);accounts.forEach(a=>{const btn=Array.from(box.querySelectorAll('[data-action=activate-user]')).find(b=>b.dataset.id===a.id);if(btn){const field=document.createElement('label');field.className='field';field.innerHTML=`<span>باقة الاشتراك</span><select data-plan-account="${esc(a.id)}" aria-label="باقة ${esc(a.name)}">${planOptions(RijaaPlans.forAccount(a).id)}</select>`;btn.closest('td').prepend(field);}});return box.innerHTML;};
const planSubscription=subscriptionHTML;
subscriptionHTML=function(){const a=shopAccount(),p=RijaaPlans.forAccount(a),box=document.createElement('div');box.innerHTML=planSubscription();box.querySelectorAll('.page-head p,.page-head .eyebrow').forEach(e=>{if(/١٩٩|غير محدودة/.test(e.textContent))e.textContent=`باقة ${p.name} · ${a.subscription.period==='year'?p.annual:p.sale} ريال ${a.subscription.period==='year'?'سنويًا · 12 شهرًا':'شهريًا'}`;});const details=box.querySelector('.subscription-details');if(details){details.lastElementChild.innerHTML=`<span>تصاميم البطاقات</span><b>${p.cards}</b>`;details.insertAdjacentHTML('beforeend',`<div><span>الباقة</span><b>${p.name} · ${a.subscription.period==='year'?p.annual:p.sale} ريال / ${a.subscription.period==='year'?'سنة':'شهر'}</b></div><div><span>حسابات الموظفين</span><b>${p.employees}</b></div><div><span>بطاقات العملاء</span><b>غير محدودة</b></div>`);}return box.innerHTML.replace('اشتراك واحد بـ١٩٩ ريال شهريًا.',`باقة ${p.name} بـ${a.subscription.period==='year'?p.annual:p.sale} ريال ${a.subscription.period==='year'?'سنويًا · 12 شهرًا':'شهريًا'}.`).replace('بطاقات غير محدودة', 'عملاء غير محدودين');};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='billing-period'){e.preventDefault();e.stopImmediatePropagation();billingPeriod=b.dataset.period==='year'?'year':'month';render();}else if(b.dataset.action==='choose-plan'){e.preventDefault();e.stopImmediatePropagation();requestedPlan=b.dataset.plan;whatsapp();}else if(b.dataset.action==='whatsapp'){requestedPlan=publicPage?'basic':RijaaPlans.forAccount(shopAccount()).id;}else if(b.dataset.action==='issue-token'){queueMicrotask(()=>{const period=document.querySelector('#token-period');if(period&&!document.querySelector('#token-plan'))period.closest('label').insertAdjacentHTML('afterend',`<label class="field"><span>باقة التوكن</span><select id="token-plan">${planOptions(RijaaPlans.forAccount(db.accounts.find(a=>a.id===b.dataset.id)).id)}</select></label>`);});}},true);
const planStyle=document.createElement('style');planStyle.textContent='.pricing{display:block}.plans-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:28px}.plans-grid .price-card{width:auto}.plans-grid .feature-list{margin:20px 0}.plans-grid .price{white-space:nowrap}@media(max-width:850px){.plans-grid{grid-template-columns:1fr}}';planStyle.textContent+=`.plans-grid{gap:24px;padding:18px 0}.premium-plan{position:relative;border:1px solid #dce6de;border-radius:30px!important;background:linear-gradient(155deg,#ffffff,#f2f7ef)!important;color:#143b31!important;padding:30px!important;box-shadow:0 16px 44px #153c3010;transition:transform .25s,box-shadow .25s;overflow:hidden}.premium-plan:before{content:'';position:absolute;width:180px;height:180px;border-radius:50%;background:radial-gradient(circle,#c6ef873d,transparent 70%);left:-60px;top:-65px;pointer-events:none}.premium-plan:hover{transform:translateY(-6px);box-shadow:0 24px 55px #153c3026}.plan-top{position:relative;display:flex;align-items:center;justify-content:space-between;gap:12px}.plan-name{font-size:25px;font-weight:700}.discount-badge{background:#e5f5ce;color:#31582b;padding:8px 14px;border:1px solid #c2e79e;border-radius:100px;font-size:14px;font-weight:700}.plan-description{font-size:14px;color:#5d736a!important;margin:16px 0 25px!important}.plan-price-line{display:flex;align-items:center;gap:14px;font-size:12px;color:#587066;margin-bottom:8px}.plan-price-line del{font-size:18px;color:#78877f}.premium-plan .price{font-size:44px!important;letter-spacing:-1px;color:#143b31}.premium-plan .price span{display:block;font-size:14px;letter-spacing:0;margin:3px 0 22px}.premium-plan .feature-list{border-top:1px solid #dce6de;padding-top:20px;min-height:220px;font-size:14px;line-height:1.8}.premium-plan .feature-list>div{display:flex;align-items:center;gap:9px;margin-bottom:11px}.premium-plan .feature-list svg{color:#5c8a42;flex-shrink:0}.premium-plan small{display:block;font-size:12px;line-height:1.8;color:#62756b;margin-top:15px}.recommended-plan{background:linear-gradient(145deg,#153d32,#082b23)!important;border-color:#49745b;box-shadow:0 20px 55px #123b3033}.recommended-plan .plan-name,.recommended-plan .price,.recommended-plan .feature-list{color:#f5ffe9!important}.recommended-plan .plan-description,.recommended-plan small,.recommended-plan .plan-price-line{color:#bdcfc3!important}.recommended-plan .feature-list{border-color:#ffffff20}.recommended-plan .discount-badge{background:#d6ff76;color:#173a26;border-color:#d6ff76}.recommended-plan .feature-list svg{color:#d6ff76}.premium-plan .btn{border-radius:15px;min-height:50px;justify-content:center;font-weight:700}@media(prefers-reduced-motion:reduce){.premium-plan{transition:none}.premium-plan:hover{transform:none}}`;document.head.append(planStyle);
render();

document.addEventListener('pointermove',e=>{const pricing=e.target.closest('.pricing');if(!pricing)return;const r=pricing.getBoundingClientRect();pricing.style.setProperty('--ash-x',`${(e.clientX-r.left)/r.width*100}%`);pricing.style.setProperty('--ash-y',`${(e.clientY-r.top)/r.height*100}%`);},{passive:true});
